#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin

# Test: review-pr resolves its target without substituting HEAD, and its fork
# waits for its reviewers (#3892).
#
# Bug 3: a non-PR-number argument ("RETRY ... origin/main...origin/qa") was
# treated as no argument, and the skill silently reviewed whatever branch the
# working copy was on. scripts/resolve-target.sh now classifies the argument;
# this drives it against a throwaway repo with real refs.
#
# Bug 2: review-pr is `context: fork`, and its reviewers were spawned with
# run_in_background=True, so the fork ended its turn "waiting on the reviewers",
# reported completed with no verdict, and the results landed in the parent.
# The contract below keeps every reviewer spawn in the skill foreground.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"
SKILL_DIR="$REPO_ROOT/src/skills/review-pr"
RESOLVE="$SKILL_DIR/scripts/resolve-target.sh"

FAILED=0
pass() { echo "  PASS $1"; }
fail() { echo "  FAIL $1"; FAILED=$((FAILED + 1)); }

if [[ ! -f "$RESOLVE" ]]; then echo "FAIL: missing $RESOLVE"; exit 1; fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-review-target.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

REPO="$WORK/repo"
mkdir -p "$REPO"
(
  cd "$REPO"
  git init -q -b main
  git -c user.email=t@example.com -c user.name=t -c commit.gpgsign=false commit -q --allow-empty -m base
  git branch qa
  git checkout -q qa
  git -c user.email=t@example.com -c user.name=t -c commit.gpgsign=false commit -q --allow-empty -m qa-change
  git checkout -q main
  git update-ref refs/remotes/origin/main main
  git update-ref refs/remotes/origin/qa qa
)

# field <json> <key>: print one field of the resolver's JSON ("" when absent).
field() {
  node -e 'const o=JSON.parse(process.argv[1]); process.stdout.write(String(o[process.argv[2]] ?? ""))' "$1" "$2"
}

# expect <label> <kind> <key=value|-> -- <args...>
expect() {
  local label=$1 kind=$2 kv=$3
  shift 4
  local out got key want val
  out="$(cd "$REPO" && env -u ORCHESTKIT_PR_URL ORK_RESOLVE_TARGET_OFFLINE=1 bash "$RESOLVE" "$@")"
  if ! node -e 'JSON.parse(process.argv[1])' "$out"; then
    fail "$label: output is not JSON: $out"
    return 0
  fi
  got="$(field "$out" kind)"
  if [[ "$got" != "$kind" ]]; then
    fail "$label: kind=$got, want $kind ($out)"
    return 0
  fi
  if [[ "$kv" != "-" ]]; then
    key=${kv%%=*}
    want=${kv#*=}
    val="$(field "$out" "$key")"
    if [[ "$val" != "$want" ]]; then
      fail "$label: $key=$val, want $want ($out)"
      return 0
    fi
  fi
  pass "$label"
}

echo "resolve-target.sh"
expect "bare PR number" pr number=123 -- 123
expect "hash PR number" pr number=42 -- '#42'
expect "PR URL" pr number=77 -- https://github.com/o/r/pull/77
expect "three-dot range" range head=origin/qa -- origin/main...origin/qa
expect "two-dot range" range op=.. -- main..qa
expect "the #3892 free-text argument resolves to its range" range base=origin/main -- "RETRY - target: next-release delta origin/main...origin/qa (bundles #1837, #1862, #1867)"
expect "a branch name" ref ref=qa -- qa
expect "a word that is not a target asks" ask - -- RETRY
expect "no argument and no PR asks (never HEAD)" ask - --
expect "a range side that does not resolve asks" ask - -- origin/main...origin/nope
expect "two PR numbers ask" ask - -- 12 34
expect "an option-looking token is not a ref" ask - -- --output=/etc/passwd

out="$(cd "$REPO" && ORCHESTKIT_PR_URL=https://github.com/o/r/pull/9 ORK_RESOLVE_TARGET_OFFLINE=1 bash "$RESOLVE")"
if [[ "$(field "$out" kind)" == pr && "$(field "$out" number)" == 9 ]]; then
  pass "ORCHESTKIT_PR_URL with no argument"
else
  fail "ORCHESTKIT_PR_URL with no argument ($out)"
fi

echo "SKILL.md and fork-wait contract"
# node prints its own PASS/FAIL lines and exits with its failure count.
contract_rc=0
node -e '
  const fs = require("fs");
  const path = require("path");
  const [skillPath, rulesDir] = process.argv.slice(1);
  const skill = fs.readFileSync(skillPath, "utf8");
  let failed = 0;
  const check = (ok, passMsg, failMsg) => {
    console.log(ok ? `  PASS ${passMsg}` : `  FAIL ${failMsg}`);
    if (!ok) failed++;
  };
  check(skill.includes("scripts/resolve-target.sh"), "Argument Resolution runs resolve-target.sh", "SKILL.md does not run resolve-target.sh");
  check(skill.includes("Never substitute `HEAD`"), "states the never-substitute-HEAD rule", "SKILL.md lost the never-substitute-HEAD rule");
  check(!skill.includes("PR_NUMBER = \"$ARGUMENTS[0]\""), "no raw ARGUMENTS[0] PR number", "SKILL.md still takes ARGUMENTS[0] as the PR number");
  if (/^context:\s*fork\s*$/m.test(skill)) {
    const files = [skillPath, ...fs.readdirSync(rulesDir).filter((f) => f.endsWith(".md")).map((f) => path.join(rulesDir, f))];
    const bad = [];
    for (const file of files) {
      const lines = fs.readFileSync(file, "utf8").split("\n");
      // A code block right after an "Incorrect" label may show the broken shape.
      let pendingIncorrect = false;
      let inFence = false;
      let fenceIsIncorrect = false;
      lines.forEach((line, i) => {
        if (/^\s*```/.test(line)) {
          if (inFence) {
            inFence = false;
            fenceIsIncorrect = false;
          } else {
            inFence = true;
            fenceIsIncorrect = pendingIncorrect;
            pendingIncorrect = false;
          }
          return;
        }
        if (!inFence && line.includes("Incorrect")) pendingIncorrect = true;
        if (!line.includes("run_in_background=True")) return;
        if (inFence && fenceIsIncorrect) return;
        bad.push(`${path.basename(file)}:${i + 1}`);
      });
    }
    check(bad.length === 0, "reviewer spawns in the fork skill are foreground", `background reviewer spawns in a fork skill: ${bad.join(", ")}`);
  } else {
    check(true, "skill is not a fork (background spawns are fine)", "");
  }
  process.exit(failed);
' "$SKILL_DIR/SKILL.md" "$SKILL_DIR/rules" || contract_rc=$?
FAILED=$((FAILED + contract_rc))

if (( FAILED > 0 )); then
  echo "FAILED: $FAILED check(s)"
  exit 1
fi
echo "All review-pr target and wait checks passed"
